use serde_json::json;
use sqlx::{PgPool, Row};
use crate::error::ApiError;
use super::{dtos::{OperationStarted, StartOperationRequest}, support::profile_stats};

pub async fn start(pool: &PgPool, user_id: i64, input: StartOperationRequest) -> Result<OperationStarted, ApiError> {
    if input.target_user_id == user_id { return Err(ApiError::BadRequest("an operation needs another player as target".into())); }
    let attacker = sqlx::query("SELECT p.*,s.id AS software_id,c.action_kind,c.grants_login FROM software_profiles p JOIN software s ON s.id=p.software_id JOIN software_running r ON r.soft_id=s.id JOIN software_capabilities c ON c.id=p.capability_id AND c.code=$2 WHERE s.user_id=$1 AND NOT s.is_npc ORDER BY p.effectiveness+p.penetration DESC LIMIT 1").bind(user_id).bind(&input.capability).fetch_optional(pool).await?.ok_or(ApiError::BadRequest("run a compiled program with that capability first".into()))?; let software_id: i64 = attacker.get("software_id"); let action_kind: String = attacker.get("action_kind"); let grants_login: Option<String> = attacker.get("grants_login"); let attacker_stats = profile_stats(&attacker);
    let defender = sqlx::query("SELECT p.* FROM software_profiles p JOIN software s ON s.id=p.software_id JOIN software_running r ON r.soft_id=s.id JOIN capability_counters x ON x.defender_capability_id=p.capability_id WHERE s.user_id=$1 AND NOT s.is_npc AND x.attacker_capability_id=(SELECT id FROM software_capabilities WHERE code=$2) ORDER BY p.effectiveness+p.detection+p.removal DESC LIMIT 1").bind(input.target_user_id).bind(&input.capability).fetch_optional(pool).await?; let defender_stats = defender.as_ref().map(profile_stats).unwrap_or_default();
    let hardware = sqlx::query("SELECT COALESCE(sum(cpu),0)::integer cpu,COALESCE(sum(ram),0)::integer ram,COALESCE(sum(net),0)::integer net FROM hardware WHERE user_id=$1 AND NOT is_npc").bind(user_id).fetch_one(pool).await?; let cpu: i32 = hardware.get("cpu"); let ram: i32 = hardware.get("ram"); let net: i32 = hardware.get("net"); if cpu < attacker_stats.cpu || ram < attacker_stats.ram || net < attacker_stats.net { return Err(ApiError::BadRequest("hardware cannot run this operation".into())); }
    let work_units = (120 + defender_stats.effectiveness + defender_stats.detection + defender_stats.removal - attacker_stats.penetration).max(40); let power = (attacker_stats.effectiveness + attacker_stats.penetration + attacker_stats.stability).max(1); let pressure = (attacker_stats.cpu * 100 / cpu.max(1)).max((attacker_stats.ram * 100 / ram.max(1)).max(attacker_stats.net * 100 / net.max(1))); let seconds = ((work_units * 10) / (power * 100 / (100 + pressure)).max(1)).clamp(20, 900);
    let snapshot = json!({"cpu":attacker_stats.cpu,"ram":attacker_stats.ram,"net":attacker_stats.net,"attacker":attacker_stats,"defender":defender_stats}); let payload = json!({"capability":input.capability,"target_user_id":input.target_user_id,"action_kind":action_kind,"grants_login":grants_login,"attack_effectiveness":attacker_stats.effectiveness,"attack_penetration":attacker_stats.penetration,"attack_stealth":attacker_stats.stealth,"defense_effectiveness":defender_stats.effectiveness,"defense_detection":defender_stats.detection,"defense_removal":defender_stats.removal});
    let process_id: i64 = sqlx::query_scalar("INSERT INTO processes(creator_id,victim_id,action,soft_id,info,info_str,time_end,time_ideal,status,started_at,resource_snapshot,process_payload) VALUES($1,$2,90,$3,$4,$4,now()+($5::integer*interval '1 second'),$5,'running',now(),$6,$7) RETURNING pid").bind(user_id).bind(input.target_user_id).bind(software_id).bind(&input.capability).bind(seconds).bind(snapshot).bind(payload).fetch_one(pool).await?;
    Ok(OperationStarted { process_id, seconds, capability: input.capability, work_units, attacker: attacker_stats, defender: defender_stats })
}
